    descricao: "Também conhecido como Parasita de Dimensões: uma entidade suprema que consome a entropia de tudo que é vivo, com o crânio exposto e Lodo escorrendo dos olhos como lágrimas pretas. Tudo termina, tudo retorna — uma relíquia consciente e onipresente, num ciclo eterno de fim e renascimento.",
