    enigmaDoMedo: "O ciborgue é programado pela Energia para alterar seu estado de combate com frequência. Cada estado (Alpha, Beta, Gama, Delta) possui uma fraqueza específica, determinada quando ele é criado pela entidade — por exemplo, sofrer 15 pontos de dano de um tipo específico num único ataque, ou ser exposto a uma substância ou material específico. Uma fraqueza só pode ser resolvida se o ciborgue estiver no estado de combate correspondente; quando resolvida, ele não pode mais assumir esse estado. Quando fica sem nenhum estado de combate disponível, se desativa: sua Defesa cai para 10 e seu deslocamento para 0m.",
