    descricao: "Só se origina em ambientes com a Membrana extremamente danificada e condições muito específicas, como usinas radioativas abandonadas — sons ensurdecedores que poderiam ser confundidos com raios violentos, emitindo uma radiação paranormal muito mais perigosa que a nuclear.",
